SELECT COUNT(DISTINCT id) AS release_promotion_cards_count
FROM cards
WHERE isPromo = 1 AND promoTypes LIKE '%release%' AND promoTypes NOT LIKE '%prerelease%';

WITH fireball_cards AS (
  SELECT uuid FROM cards WHERE name = 'Fireball'
)
SELECT COUNT(*) AS total_rulings_for_fireball
FROM rulings
WHERE uuid IN (SELECT uuid FROM fireball_cards);

SELECT COUNT(*) AS number_of_printings
FROM cards
WHERE CAST(power AS INTEGER) > 3 AND CAST(power AS INTEGER) <= 10;

